algorithms.pseudocode:
onPost(p):
  if followers(p.author) > 100_000:
      ZADD ar:{p.author} p.ts p.id; LTRIM to 100; return
  for page in followers(p.author, page=5000):
      for f in page:
          if lastActive(f) > now-30d:
              pipeline ZADD tl:{f} p.ts p.id
              pipeline ZREMRANGEBYRANK tl:{f} 0 -801
      pipeline.exec()
  commit offset

for c in cands:
  m = 1.0*p_like + 13*p_reply + 0.5*p_dwell - 74*p_report
  hl = 8h if c.in_network else 4h
  c.score = m * 2 ** (-(now - c.ts)/hl)
sorted = sortDesc(cands, score)
out, run = [], {}
for c in sorted:
  if last2Authors(out) == [c.author, c.author]: defer(c); continue
  out.append(c)
reinsert deferred at next legal slot

order = chronological(cands)
try within 30ms: feats = fetchFeatures()
try within 20ms: order = lightRank(order, feats)[:500]
try within 120ms: order = heavyRank(order, feats)
except Timeout: degraded = True
return mix(order)
